from statistics import mean

def calculate_signal_strength(region_data, historical_data=None):
    """
    Calculate the average signal strength per region and identify the region with the strongest average signal.
    Optionally, identify the region with the most improved signal strength over a year using historical data.

    :param region_data: Dictionary where keys are region names and values are lists of current signal strengths.
    :param historical_data: Optional dictionary where keys are region names and values are lists of historical signal strengths.
    :return: A tuple containing the average signal strengths, the region with the strongest average signal, and the region with the most improved signal strength.
    """
    if historical_data:
        improvements = {}

    strengths = {}
    for region, signals in region_data.items():
        average = mean(signals)
        strengths[region] = average

        if historical_data:
            historical_signals = historical_data.get(region)
            if historical_signals:
                improvement = average - mean(historical_signals)
                improvements[region] = improvement

    strongest_region = max(strengths, key=strengths.get)
